import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Navigationsbaum","description":"","frontmatter":{"title":"Navigationsbaum","covers":{"screens":["SCR-055"],"stories":["US-054","US-094","US-095","US-096","US-097","US-132","US-133"]}},"headers":[],"relativePath":"de/usage/navigation.md","filePath":"de/usage/navigation.md"}`),a={name:`de/usage/navigation.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="navigationsbaum" tabindex="-1">Navigationsbaum <a class="header-anchor" href="#navigationsbaum" aria-label="Permalink to “Navigationsbaum”">​</a></h1><p>Der Navigationsbaum ordnet Kataloge, Entitäten und Lösungen in Ordnern, zum Beispiel <em>IT Landscape &gt; Application Inventory</em>, damit du findest, was du für deine Aufgabe brauchst, ohne zu suchen. Alle mit der Berechtigung <code>entity:read</code> (zum Beispiel die Rolle <code>viewer</code>) sehen den Baum. Ändern lässt er sich mit den Berechtigungen <code>viewpoint:manage</code> und <code>entity:read</code> (Rolle <code>enterprise-architect</code>).</p><h2 id="die-seitenleiste" tabindex="-1">Die Seitenleiste <a class="header-anchor" href="#die-seitenleiste" aria-label="Permalink to “Die Seitenleiste”">​</a></h2><p>Nach der Anmeldung hat die Seitenleiste links auf jeder Seite zwei Tabs: <em>Browser</em> und <em>Navigationsbaum</em>. <em>Browser</em> ist beim Anmelden aktiv; der gewählte Tab bleibt aktiv, während du zwischen den Seiten wechselst (siehe <a href="#browser">Browser</a>). <em>Navigationsbaum</em> zeigt den folgenden Baum. Er beginnt beim Ordner <em>Repository</em>.</p><ul><li><strong>Ordner auf- und zuklappen:</strong> Wähle den Pfeil oder den Namen des Ordners. Die Seitenleiste merkt sich die offenen Ordner, bis du den Browser-Tab schliesst.</li><li><strong>Eintrag öffnen:</strong> Wähle ihn. Ein Katalog öffnet sich mit seiner Standardansicht, falls er eine hat (siehe <a href="./catalogs#views">Ansichten</a>); eine Entität öffnet ihre Seite, eine Lösung ihre Lösungsseite.</li><li><strong>Schmale Bildschirme:</strong> Die Seitenleiste ist ausgeblendet; die Menü-Schaltfläche links in der Kopfzeile öffnet sie. Wählst du einen Eintrag, schliesst sie sich wieder.</li></ul><p>Ordner und Einträge behalten die Reihenfolge, in der du sie anordnest (siehe <a href="#reorganize-the-tree">Baum umorganisieren</a>); neue Ordner und Einträge kommen ans Ende. Ein Eintrag zeigt seinen Anzeigenamen, falls er einen hat, sonst den Namen des Katalogs, der Entität oder der Lösung. Ein Symbol zeigt die Art des Eintrags, ein Personen-Symbol kennzeichnet einen persönlichen Katalog.</p><h2 id="browser" tabindex="-1">Browser <a class="header-anchor" href="#browser" aria-label="Permalink to “Browser”">​</a></h2><p>Der Tab <em>Browser</em> braucht keine Handarbeit: Er listet auf, was das Repository enthält, geordnet nach Lösungen. Alle mit der Berechtigung <code>entity:read</code> sehen ihn. Von oben nach unten zeigt er:</p><ol><li><strong>Ist-Zustand:</strong> die Objekte des Repositorys, wie sie jetzt sind, in den Kategorien <em>Komponenten</em> (Entitäten, die keine Verbindungen und nicht gelöscht sind), <em>Verbindungen</em> und <em>Kataloge</em> (die Kataloge, die du siehst: gemeinsame und deine eigenen persönlichen).</li><li><strong>Plateaus:</strong> ein Knoten für jedes Plateau im Status <em>transition</em> oder <em>target</em>, geordnet nach dem Datum, ab dem es gilt, dann nach Name. Das Baseline-Plateau und realisierte Plateaus haben keinen Knoten. Unter einem Plateau stehen die Lösungen, die es als Ziel haben, nach Name sortiert.</li><li><strong>Projekte:</strong> die Lösungen ohne Plateaus, nach Name sortiert.</li></ol><p>Es erscheinen nur aktive Lösungen: Eine Lösung im Status <em>implemented</em> oder <em>archived</em> wird nicht aufgeführt. Die Entitäten einer umgesetzten Lösung zählen unter <em>Ist-Zustand</em>. Ein Plateau oder <em>Projekte</em> ohne Lösungen bleibt sichtbar und erscheint als <em>(0)</em>.</p><p>Jede Lösung hat die Kategorie <em>Komponenten</em>: ihre Änderungen am Repository, gekennzeichnet als <em>Neu</em>, <em>Geändert</em> oder <em>Auslaufend</em>. Jede Kategorie zeigt, wie viele Objekte sie enthält. Eine leere Kategorie ist ausgegraut, nicht ausgeblendet.</p><ul><li><strong>Knoten aufklappen:</strong> Wähle den Pfeil oder den Namen. Eine Kategorie lädt ihre Objekte, wenn du sie zum ersten Mal aufklappst; sie listet sie nach Name, je 50. Mit <em>Mehr laden</em> folgen die nächsten 50.</li><li><strong>Objekt öffnen:</strong> Eine Entität öffnet ihre Änderungshistorie, ein Katalog seine Seite, eine Änderung einer Lösung (und das Link-Symbol neben einer Lösung) die Lösungsseite.</li><li><strong>Metatyp:</strong> Ein kleines Label neben einer Entität zeigt die Abkürzung ihres Metatyps, falls er eine hat.</li></ul><p>Der Browser zeigt nur an; den Baum ordnest du im Tab <em>Navigationsbaum</em>. Funktionale und Lösungs-Bausteine sowie Diagramme folgen mit ihren Inhalten.</p><h2 id="ordner" tabindex="-1">Ordner <a class="header-anchor" href="#ordner" aria-label="Permalink to “Ordner”">​</a></h2><p>Mit den Berechtigungen zum Ändern des Baums bietet die Schaltfläche <em>…</em> neben einem Ordner:</p><ul><li><strong>Neuer Ordner:</strong> legt einen Ordner darin an. Gib einen Namen ein und wähle <em>Erstellen</em>.</li><li><strong>Umbenennen:</strong> ändert den Namen des Ordners, auch des Ordners <em>Repository</em>. Seine Einträge und Unterordner bleiben.</li><li><strong>Nach oben</strong>, <strong>Nach unten</strong> und <strong>Verschieben nach…:</strong> siehe <a href="#reorganize-the-tree">Baum umorganisieren</a>.</li><li><strong>Löschen:</strong> fragt zuerst nach und nennt, wie viele Unterordner und Einträge das Löschen entfernt. Der Ordner wird mit allen Unterordnern und Einträgen gelöscht. <strong>Kein Katalog, keine Entität und keine Lösung wird gelöscht</strong>; sie bleiben verfügbar und in anderen Ordnern. Der Ordner <em>Repository</em> lässt sich nicht löschen.</li></ul><p>Ein Ordnername hat 1 bis 255 Zeichen und ist in seinem Ordner eindeutig, unabhängig von Gross- und Kleinschreibung; sonst meldet der Dialog <em>Ein Ordner mit diesem Namen existiert bereits</em>. Der Baum hat höchstens 10 Ebenen unter <em>Repository</em> und höchstens 500 Ordner.</p><h2 id="katalog-entitat-oder-losung-einordnen" tabindex="-1">Katalog, Entität oder Lösung einordnen <a class="header-anchor" href="#katalog-entitat-oder-losung-einordnen" aria-label="Permalink to “Katalog, Entität oder Lösung einordnen”">​</a></h2><ol><li>Wähle <em>In Navigation einordnen</em>: <ul><li>für einen Katalog auf der Seite des Katalogs;</li><li>für eine Entität in ihrer Zeile eines Katalogs (nicht in Katalogen von Verbindungen);</li><li>für eine Lösung in der Kopfzeile der Lösungsseite.</li></ul></li><li>Wähle unter <em>Ordner</em> den Ordner über seinen Pfad, zum Beispiel <em>Repository / IT Landscape</em>.</li><li>Gib bei Bedarf einen <em>Anzeigenamen</em> ein. Der Baum zeigt ihn dann statt des Namens, zum Beispiel <em>System Inventory</em> für <em>Application Inventory</em>. Katalog, Entität oder Lösung behalten ihren Namen.</li><li>Wähle <em>Einordnen</em>.</li></ol><p>Jedes davon kann in mehreren Ordnern stehen, aber nur einmal pro Ordner. Ein Ordner hat höchstens 200 Einträge. Enthält der Ordner es bereits oder ist er voll, meldet der Dialog das, zum Beispiel <em>Der Katalog ist bereits in diesem Ordner, oder der Ordner ist voll</em>.</p><h2 id="reorganize-the-tree" tabindex="-1">Baum umorganisieren <a class="header-anchor" href="#reorganize-the-tree" aria-label="Permalink to “Baum umorganisieren”">​</a></h2><p>Mit den Berechtigungen zum Ändern des Baums ordnest du Ordner und Einträge in der Seitenleiste an:</p><ul><li><strong>Ziehen und Ablegen:</strong> Ziehe einen Ordner oder Eintrag an eine andere Stelle im selben Ordner oder in einen anderen Ordner. Wo er nicht hin kann, zeigt die Seitenleiste <em>Kann hier nicht abgelegt werden</em>, zum Beispiel bei einem Ordner, der in seinen eigenen Unterordner gezogen wird.</li><li><strong>Ohne Maus:</strong> Die Schaltfläche <em>…</em> neben einem Ordner oder Eintrag bietet <em>Nach oben</em>, <em>Nach unten</em> und <em>Verschieben nach…</em>. <em>Verschieben nach…</em> fragt nach dem Zielordner und verschiebt ans Ende dieses Ordners.</li></ul><p>Eine Verschiebung hält die Regeln des Baums ein: höchstens 10 Ebenen, höchstens 200 Einträge pro Ordner, eindeutige Ordnernamen und ein Eintrag nur einmal pro Ordner. Umsortieren innerhalb eines vollen Ordners ist möglich. Sonst meldet die Seitenleiste <em>Das kann nicht dorthin verschoben werden. Der Baum hat sich eventuell inzwischen geändert.</em> Gibt es einen Ordner oder Eintrag nicht mehr, weil jemand anderes den Baum inzwischen geändert hat, liest die Seitenleiste den aktuellen Baum neu.</p><h2 id="eintrag-aus-dem-baum-entfernen" tabindex="-1">Eintrag aus dem Baum entfernen <a class="header-anchor" href="#eintrag-aus-dem-baum-entfernen" aria-label="Permalink to “Eintrag aus dem Baum entfernen”">​</a></h2><p>Die Schaltfläche <em>×</em> neben einem Eintrag entfernt ihn aus diesem Ordner. Nur dieser Eintrag wird entfernt: Katalog, Entität oder Lösung selbst und ihre Einträge in anderen Ordnern bleiben.</p><h2 id="geloschte-entitaten" tabindex="-1">Gelöschte Entitäten <a class="header-anchor" href="#geloschte-entitaten" aria-label="Permalink to “Gelöschte Entitäten”">​</a></h2><p>Wird eine Entität gelöscht, bleiben ihre Einträge im Baum und zeigen die Markierung <em>Gelöscht</em>. Entferne sie mit <em>×</em>, oder stelle die Entität wieder her; dann verschwindet die Markierung.</p><h2 id="personliche-kataloge" tabindex="-1">Persönliche Kataloge <a class="header-anchor" href="#personliche-kataloge" aria-label="Permalink to “Persönliche Kataloge”">​</a></h2><p>Deinen eigenen persönlichen Katalog kannst du wie einen geteilten einordnen. Nur du siehst seinen Eintrag: Der Baum zeigt nie die persönlichen Kataloge anderer, er führt also nie zu einem Katalog, den du nicht öffnen kannst. Teilst du den Katalog später, sehen alle den Eintrag.</p><p>Jede Änderung des Baums, auch jede Verschiebung, wird im Audit-Trail festgehalten.</p><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><ul><li><code>GET /views/browser</code> liefert die oberste Ebene des Browsers: <code>currentState</code> mit den Zahlen <code>components</code>, <code>connections</code> und <code>catalogs</code>, <code>plateaus</code> (jedes mit seinen <code>solutions</code>) und <code>projects</code>; eine Lösung hat <code>id</code>, <code>name</code>, <code>status</code> und die Zahl ihrer Änderungen in <code>components</code>.</li><li><code>GET /views/browser/items</code> liefert eine Seite einer Kategorie, nach Name geordnet: <code>scope</code> (<code>current-state</code> oder <code>solution</code>), <code>category</code> (<code>components</code>, <code>connections</code> oder <code>catalogs</code>; eine Lösung hat nur <code>components</code>), <code>solutionId</code> für eine Lösung sowie <code>page</code> und <code>pageSize</code> (1 bis 200, Standard 50). Eine <code>pageSize</code> ausserhalb von 1 bis 200 wird mit 400 abgewiesen; eine Kategorie, die der Bereich nicht hat, oder eine <code>solutionId</code>, die nicht zum Bereich passt, mit 422 und dem Namen <code>category</code> oder <code>solutionId</code>; eine unbekannte Lösung mit 404.</li><li><code>GET /views/explorer</code> liefert den Baum ab der Wurzel so, wie du ihn siehst, in seiner manuellen Reihenfolge: jeden Ordner mit <code>id</code>, <code>name</code>, <code>parentId</code>, <code>sortOrder</code>, <code>items</code> und <code>children</code>; jeden Eintrag mit <code>itemType</code> (<code>catalog</code>, <code>entity</code> oder <code>solution</code>), <code>referenceId</code> (Katalog- oder Lösungs-ID) oder <code>entityId</code>, <code>displayLabel</code>, <code>name</code>, <code>scope</code> und <code>deleted</code>.</li><li><code>POST /tree-nodes</code> mit <code>name</code> und <code>parentId</code> legt einen Ordner an; <code>PATCH /tree-nodes/{nodeId}</code> mit <code>name</code> benennt ihn um; <code>DELETE /tree-nodes/{nodeId}</code> löscht ihn.</li><li><code>POST /tree-nodes/{nodeId}/items</code> mit <code>itemType</code>, <code>referenceId</code> oder <code>entityId</code> und einem optionalen <code>displayLabel</code> ordnet einen Eintrag ein; <code>DELETE /tree-nodes/{nodeId}/items/{itemId}</code> entfernt ihn.</li><li><code>PUT /tree-nodes/{nodeId}/position</code> mit <code>parentId</code> und <code>position</code> verschiebt einen Ordner; <code>PUT /tree-nodes/{nodeId}/items/{itemId}/position</code> mit <code>nodeId</code> und <code>position</code> verschiebt einen Eintrag. Die Position zählt die Einträge, die du siehst, ab 0.</li></ul><p>Jede Änderung antwortet mit dem ganzen Baum. Ungültige Eingaben werden mit 422 abgelehnt und nennen das Feld in <code>invalidFields</code>, zum Beispiel <code>name</code> für einen vergebenen Ordnernamen, <code>parentId</code> für eine Verschiebung, die einen Zyklus bilden oder zu tief gehen würde, oder <code>nodeId</code> für einen Zielordner, der den Eintrag schon enthält oder voll ist.</p>`,34)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};